return get(first(ctx.lookup.days_by_region.filter((row) => row.region === get(ctx.subject.employer, 'entity_extension_data.region', ''))), 'days', 0);

// js
// 上海市人口与计划生育条例 第三十一条: 子女年满3周岁前, 按子女数每年5天; 云南省人口与计划生育条例 第十八条: 子女不满3周岁每年10天, 两个以上15天.
const region = get(ctx.subject.employer, 'entity_extension_data.region', '');
const young = get(ctx.subject.employment, 'events', []).filter((event) => event.kind === 'CHILD_BIRTH' && event.on <= ctx.as_of && age_on(event.on, ctx.as_of) < ctx.lookup.child_age_limit_years).length;
const each = first(ctx.lookup.per_child_days_by_region.filter((row) => row.region === region));
if (each != null) return each.days * young;
return get(ctx.lookup.days_by_children_by_region.filter((row) => row.region === region && row.children <= young).at(-1), 'days', 0);

